CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS codes (email_hash TEXT PRIMARY KEY, code_hash TEXT NOT NULL, exp INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, last_sent INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS tokens (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT NOT NULL, ts INTEGER NOT NULL, track_id TEXT NOT NULL, title TEXT, artist TEXT, thumb TEXT, ms INTEGER NOT NULL DEFAULT 0, UNIQUE(user_id, ts, track_id));
CREATE INDEX IF NOT EXISTS idx_events_user_ts ON events(user_id, ts);
CREATE TABLE IF NOT EXISTS tg_sessions (sid_hash TEXT PRIMARY KEY, exp INTEGER NOT NULL, user_id TEXT, token TEXT);
CREATE TABLE IF NOT EXISTS rl (k TEXT PRIMARY KEY, n INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sid_users (email_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE, salt TEXT NOT NULL, pw_hash TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sid_tokens (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sid_likes (user_id TEXT NOT NULL, track_id TEXT NOT NULL, title TEXT, artist TEXT, thumb TEXT, dur INTEGER NOT NULL DEFAULT 0, ts INTEGER NOT NULL, PRIMARY KEY(user_id, track_id));
CREATE TABLE IF NOT EXISTS sid_ded (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, from_name TEXT, to_name TEXT, msg TEXT, track_id TEXT NOT NULL, title TEXT, artist TEXT, thumb TEXT, ts INTEGER NOT NULL, hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sid_ded_reports (ded_id TEXT NOT NULL, user_id TEXT NOT NULL, PRIMARY KEY(ded_id, user_id));
CREATE TABLE IF NOT EXISTS sid_mail (user_id TEXT PRIMARY KEY, email_enc TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 0, code_hash TEXT NOT NULL DEFAULT '', exp INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, last_sent INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sid_ded_meta (ded_id TEXT PRIMARY KEY, user_id TEXT NOT NULL, ip_hash TEXT NOT NULL DEFAULT '', ts INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_ded_meta_ip ON sid_ded_meta(ip_hash);
CREATE TABLE IF NOT EXISTS sid_ban (k TEXT PRIMARY KEY, ts INTEGER NOT NULL);
